  'ref.heroTitle': { ru: 'Дарите скидку {percent}% друзьям и получайте {reward} бонусами за их первый заказ', en: 'Give your friends {percent}% off and get {reward} in bonuses on their first order', it: 'Regala ai tuoi amici il {percent}% di sconto e ricevi {reward} in bonus sul loro primo ordine', fr: 'Offrez {percent} % de remise à vos amis et recevez {reward} de bonus sur leur première commande', de: 'Schenken Sie Freunden {percent} % Rabatt und erhalten Sie {reward} Bonus für ihre erste Bestellung' },
  'ref.heroHow': { ru: 'Поделитесь ссылкой. Друг получит скидку на первый заказ, а вы — бонусы, как только этот заказ будет оплачен.', en: 'Share your link. Your friend gets a discount on their first order, and you get the bonus once that order is paid.', it: 'Condividi il tuo link. Il tuo amico riceve uno sconto sul primo ordine e tu il bonus non appena l\'ordine è pagato.', fr: 'Partagez votre lien. Votre ami obtient une remise sur sa première commande, et vous le bonus dès qu\'elle est payée.', de: 'Teilen Sie Ihren Link. Ihr Freund erhält Rabatt auf die erste Bestellung, Sie den Bonus, sobald sie bezahlt ist.' },
