  'cookies.analyticsHint': { ru: 'Google Analytics 4: помогает понять, какие страницы полезны. Статистика обезличена.', en: 'Google Analytics 4: helps us see which pages are useful. Reports are aggregated.', it: 'Google Analytics 4: ci aiuta a capire quali pagine sono utili. I report sono aggregati.', fr: 'Google Analytics 4 : nous aide à voir quelles pages sont utiles. Les rapports sont agrégés.', de: 'Google Analytics 4: zeigt uns, welche Seiten nützlich sind. Die Berichte sind aggregiert.' },
