  'footer.newsInvalid': { ru: 'Проверьте адрес электронной почты', en: 'Check the email address', it: 'Controlla l\'indirizzo email', fr: 'Vérifiez l\'adresse e-mail', de: 'Prüfen Sie die E-Mail-Adresse' },
