  'unsub.resubscribedBody': { ru: 'Рады, что вы остаётесь с нами.', en: 'Glad to have you back.', it: 'Felici di riaverti con noi.', fr: 'Ravis de vous retrouver.', de: 'Schön, dass Sie wieder dabei sind.' },
  'unsub.invalidTitle': { ru: 'Ссылка недействительна', en: 'This link is not valid', it: 'Link non valido', fr: 'Ce lien n\'est pas valide', de: 'Dieser Link ist ungültig' },
  'unsub.invalidBody': { ru: 'Возможно, она скопирована не полностью. Напишите нам — отпишем вручную.', en: 'It may have been copied incompletely. Write to us and we\'ll unsubscribe you by hand.', it: 'Potrebbe essere stato copiato in modo incompleto. Scrivici e ti rimuoveremo manualmente.', fr: 'Il a peut-être été copié partiellement. Écrivez-nous et nous vous désabonnerons manuellement.', de: 'Er wurde vielleicht unvollständig kopiert. Schreiben Sie uns, wir melden Sie manuell ab.' },
